    private TextView text(String value,int size){TextView view=new TextView(this);L10n.setText(view,value);view.setTextSize(size);view.setTextColor(0xffedf3f8);return view;}
    private void row(LinearLayout root,String[] labels,Runnable[] actions){LinearLayout row=new LinearLayout(this);for(int i=0;i<labels.length;i++){Button b=new Button(this);L10n.setText(b,labels[i]);b.setAllCaps(false);final Runnable action=actions[i];b.setTextSize(11);b.setMinWidth(0);b.setPadding(4,6,4,6);boolean recovery=labels[i].equals("Recovery")||labels[i].equals("Help")||labels[i].equals("Restart lab")||labels[i].equals("Language");b.setTag(R.id.recovery_control,recovery);b.setOnClickListener(v->{if(!busy||Boolean.TRUE.equals(b.getTag(R.id.recovery_control)))action.run();});buttons.add(b);row.addView(b,new LinearLayout.LayoutParams(0,-2,1));}root.addView(row);}
    private void setEnabled(boolean value){for(Button b:buttons)b.setEnabled(value||Boolean.TRUE.equals(b.getTag(R.id.recovery_control)));command.setEnabled(value);}
    private void restartLab(){new UiDialog(this).setTitle("Restart document lab?").setMessage("Unsaved lab documents will close. Saved FCStd files and macros are kept. The CAD workspace stays in its separate process.").setNegativeButton("Cancel",null).setPositiveButton("Restart",(d,w)->{startActivity(new Intent(this,StartupActivity.class).putExtra("diagnostics_only",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP));android.os.Process.killProcess(android.os.Process.myPid());}).show();}
    private interface Task{JSONObject run()throws Exception;}
    private void job(Task task){if(busy)return;busy=true;setEnabled(false);L10n.setText(status,"Working…");worker.execute(()->{try{JSONObject next=task.run();runOnUiThread(()->{if(destroyed)return;busy=false;setEnabled(true);state=next;render();});}catch(Throwable e){Diagnostics.error(this,"Upstream document operation",e);runOnUiThread(()->{if(destroyed)return;busy=false;setEnabled(true);error(e);});}});}
    private JSONObject request(String text)throws Exception{JSONObject result=new JSONObject(CoreNative.request(text));if(!result.getBoolean("ok"))throw new IOException(result.getString("error"));return result.getJSONObject("state");}
    private JSONObject request(JSONObject json)throws Exception{return request(json.toString());}
    private void send(String action){job(()->request(new JSONObject().put("op",action)));}
    private void edit(JSONObject edit){job(()->request(new JSONObject().put("op","batch").put("edits",new JSONArray().put(edit))));}
    private void render(){try{renderPython();StringBuilder b=new StringBuilder();JSONObject doc=state.optJSONObject("document");if(state.has("body_inspection")){new UiDialog(this).setTitle("Inspect Body history").setMessage(state.getJSONObject("body_inspection").toString(2)).setPositiveButton("OK",null).show();state.remove("body_inspection");}if(state.has("element_inspection")){new UiDialog(this).setTitle("Inspect native face or edge").setMessage(state.getJSONObject("element_inspection").toString(2)).setPositiveButton("OK",null).show();state.remove("element_inspection");}if(state.has("wire_preview")){if(partPreview!=null)partPreview.dismiss();partPreview=NativeWirePreview.show(this,state.getJSONObject("wire_preview"));state.remove("wire_preview");}if(state.has("shape_inspection")){new UiDialog(this).setTitle("Exact native shape measurements").setMessage(state.getJSONObject("shape_inspection").toString(2)).setPositiveButton("OK",null).show();state.remove("shape_inspection");}if(state.has("sketch_inspection")){new UiDialog(this).setTitle("Inspect sketch solver").setMessage(state.getJSONObject("sketch_inspection").toString(2)).setPositiveButton("OK",null).show();state.remove("sketch_inspection");}if(state.has("sketch_preview")){if(partPreview!=null)partPreview.dismiss();partPreview=SketchPreview.show(this,state.getJSONObject("sketch_preview"));state.remove("sketch_preview");}if(state.has("preview")){try{if(partPreview!=null)partPreview.dismiss();partPreview=PartPreview.show(this,state.getJSONArray("preview"));state.remove("preview");}catch(Exception e){error(e);}}if(state.has("step_file")){exportStep=state.getString("step_file");state.remove("step_file");Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.setType("application/octet-stream");intent.addCategory(Intent.CATEGORY_OPENABLE);intent.putExtra(Intent.EXTRA_TITLE,exportStep);startActivityForResult(intent,85);}L10n.setText(status,state.optBoolean("transaction")?"Transaction open · commit or cancel to finish":"Ready · changes remain editable");if(doc==null){report.setText(L10n.text(this,"Create a document or open a supported native FCStd file."));return;}b.append(doc.getString("label")).append("\nUndo: ").append(doc.getInt("undo")).append(" · Redo: ").append(doc.getInt("redo")).append("\n\n");JSONArray objects=doc.getJSONArray("objects");for(int i=0;i<objects.length();i++){JSONObject o=objects.getJSONObject(i);b.append(o.getString("name")).append(" · ").append(o.getString("label")).append("\n").append(o.getString("type")).append("\n");JSONArray props=o.getJSONArray("properties");for(int j=0;j<props.length();j++){JSONObject p=props.getJSONObject(j);Object value=p.get("value");if(value instanceof JSONObject&&((JSONObject)value).has("text"))value=((JSONObject)value).getString("text");b.append("  ").append(p.getString("name")).append(" = ").append(value).append("\n");}if(o.has("shape"))b.append("Shape: ").append(o.getJSONObject("shape")).append("\n");if(o.has("sketch"))b.append(L10n.text(this,"Sketch solver")).append(": ").append(o.getJSONObject("sketch")).append("\n");if(o.has("body"))b.append(L10n.text(this,"Body history")).append(": ").append(o.getJSONObject("body")).append("\n");b.append("Expressions: ").append(o.getJSONArray("expressions")).append("\nReferences: ").append(o.getJSONArray("dependencies")).append("\n\n");}report.setText(b.toString());}catch(Exception e){error(e);}}
    private void error(Throwable e){L10n.setText(status,"Operation failed");new UiDialog(this).setTitle("Document operation").setMessage(e.getMessage()==null?e.toString():e.getMessage()).setPositiveButton("OK",null).show();}
    private interface Fields{void accept(String[] values)throws Exception;}
    private void fields(String title,String[] labels,String[] defaults,Fields callback){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(24,10,24,10);EditText[] inputs=new EditText[labels.length];for(int i=0;i<labels.length;i++){root.addView(text(labels[i],13));EditText input=new EditText(this);input.setTextColor(0xffedf3f8);input.setText(defaults[i]);input.setSingleLine(true);inputs[i]=input;root.addView(input);}ScrollView scroll=new ScrollView(this);scroll.addView(root);new UiDialog(this).setTitle(title).setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Apply",(d,w)->{String[] values=new String[inputs.length];for(int i=0;i<inputs.length;i++)values[i]=inputs[i].getText().toString();try{callback.accept(values);}catch(Exception e){error(e);}}).show();}
