    private void macroMenu(){new UiDialog(this).setTitle("Python macros").setItems(L10n.labels(this,new String[]{"New macro","Open / edit macro","Run macro","Record document commands","Save recording","Import Python file","Export Python file"}),(d,w)->{if(w==0)fields("New macro",new String[]{"Filename"},new String[]{"MyMacro.py"},v->macroEditor(v[0],"import FreeCAD as App\nprint(App.Version())\n"));else if(w==1||w==2)fields(w==1?"Edit macro":"Run macro",new String[]{"Filename"},new String[]{"MyMacro.py"},v->job(()->request(new JSONObject().put("op",w==1?"macro_read":"macro_run").put("name",v[0]))));else if(w==3)send("record_start");else if(w==4)fields("Save recording",new String[]{"Filename"},new String[]{"Recorded.py"},v->job(()->request(new JSONObject().put("op","record_stop").put("name",v[0]))));else if(w==5){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,83);}else fields("Export macro",new String[]{"Filename"},new String[]{"MyMacro.py"},v->{exportMacro=v[0];if(!exportMacro.matches("[A-Za-z_][A-Za-z_0-9-]{0,79}\\.py"))throw new IOException("Use a plain .py filename");Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("text/x-python");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,exportMacro);startActivityForResult(i,84);});}).show();}
