    @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(code==86){job(()->{String stamp=Long.toString(System.currentTimeMillis()),name="Imported-"+stamp+".step";File file=new File(documents,name);try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(file)){if(in==null)throw new IOException("Cannot open STEP input");copy(in,out,128L*1024*1024);}catch(Exception e){file.delete();throw e;}return request(new JSONObject().put("op","part_import").put("name","ImportedStep"+stamp).put("file",name));});return;}if(code==85){if(exportStep==null)return;job(()->{try(InputStream in=new FileInputStream(new File(documents,exportStep));OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Cannot open STEP output");copy(in,out,128L*1024*1024);}return request("{\"op\":\"state\"}");});return;}if(code==83){job(()->{String name="Imported-"+System.currentTimeMillis()+".py";java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Cannot open macro");copy(in,bytes,65536);}String source=java.nio.charset.StandardCharsets.UTF_8.newDecoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(bytes.toByteArray())).toString();if(source.startsWith("\ufeff"))source=source.substring(1);return request(new JSONObject().put("op","macro_save").put("name",name).put("code",source));});return;}if(code==84){final String name=exportMacro;job(()->{JSONObject loaded=request(new JSONObject().put("op","macro_read").put("name",name));try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Cannot open macro output");out.write(loaded.getString("macro_source").getBytes(java.nio.charset.StandardCharsets.UTF_8));}return request("{}");});return;}if(code==81)job(()->{String name="Imported-"+System.currentTimeMillis()+".FCStd";File file=new File(documents,name);try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(file)){if(in==null)throw new IOException("Cannot open input");copy(in,out,128L*1024*1024);}catch(Exception e){file.delete();throw e;}return request(new JSONObject().put("op","open").put("file",name));});else if(code==82){final String name=exportFile;job(()->{try(InputStream in=new FileInputStream(new File(documents,name));OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Cannot open output");copy(in,out,128L*1024*1024);}return request("{}");});}}
    private static void copy(InputStream in,OutputStream out,long maximum)throws IOException{byte[] buffer=new byte[65536];long total=0;int n;while((n=in.read(buffer))!=-1){total+=n;if(total>maximum)throw new IOException("File exceeds "+maximum+" bytes");out.write(buffer,0,n);}}
